-- MARE CUKCUK handover seed. Generated from local CUKCUK exports.
-- Source period: menu export 2026-09-20; revenue 2026-09-01..2026-09-22; stock summary file exported 2026-09-20.
-- Rerunnable: deterministic UUIDs are derived with md5(...).
BEGIN;

VALUES (md5('mare:tenant')::uuid, NOW(), 'mare.anhmedia.vn', 'MARE', 'SHOP', TRUE)
ON CONFLICT (tenant_code) DO UPDATE SET tenant_name=EXCLUDED.tenant_name, tenant_type='SHOP', is_active=TRUE;

VALUES (md5('mare:company:cho-lon')::uuid, 'MARE', 'MARE - CN Chợ Lớn', NOW(), md5('mare:tenant')::uuid, '0942064949', 'Số 60 đường số 23, Phường Bình Phú, TP Hồ Chí Minh', 1907, FALSE, TRUE, TRUE, 'MARE', 'Số 60 đường số 23, Phường Bình Phú, TP Hồ Chí Minh', '0942064949')
ON CONFLICT (id) DO UPDATE SET company_code=EXCLUDED.company_code, company_name=EXCLUDED.company_name, tenant_id=EXCLUDED.tenant_id, phone_number=EXCLUDED.phone_number, address=EXCLUDED.address, last_order_number=GREATEST(COALESCE(company.last_order_number,0), EXCLUDED.last_order_number), realtime_inventory=TRUE, shop_processing_inventory_recheck=TRUE, shop_name=EXCLUDED.shop_name, shop_address=EXCLUDED.shop_address, shop_phone=EXCLUDED.shop_phone;

VALUES (md5('mare:warehouse:cho-lon')::uuid, md5('mare:tenant')::uuid, md5('mare:company:cho-lon')::uuid, 'MARE-CHO-LON', 'MARE Chợ Lớn Stock', 'CN CHỢ LỚN', TRUE, NOW(), 'Seeded from CUKCUK stock summary exported 2026-09-20')
ON CONFLICT (id) DO UPDATE SET code=EXCLUDED.code, name=EXCLUDED.name, location=EXCLUDED.location, is_active=TRUE, note=EXCLUDED.note;

ON CONFLICT (id) DO UPDATE SET table_name=EXCLUDED.table_name, is_active=TRUE;

ALTER TABLE usertb ADD COLUMN IF NOT EXISTS lasttenantid varchar(36), ADD COLUMN IF NOT EXISTS lastcompanyid varchar(36), ADD COLUMN IF NOT EXISTS assignedtenantid varchar(36), ADD COLUMN IF NOT EXISTS assignedcompanyid varchar(36);
VALUES ('mare', '$2b$13$EEkMxlhMTmNWnfcWrjtwSe3oj356D3iq1mUgzslunTPHviyFQUDLK', 'MARE', 'Admin', 'mare@anhmedia.vn', TRUE, TRUE, TRUE, FALSE, TRUE, NOW(), '', 0, (md5('mare:tenant')::uuid)::text, (md5('mare:company:cho-lon')::uuid)::text, (md5('mare:tenant')::uuid)::text, (md5('mare:company:cho-lon')::uuid)::text)
ON CONFLICT (username) DO UPDATE SET password=EXCLUDED.password, firstname=EXCLUDED.firstname, lastname=EXCLUDED.lastname, email=EXCLUDED.email, isenabled=TRUE, isaccountnonexpired=TRUE, isaccountnonlocked=TRUE, iscredentialsnonexpired=TRUE, lasttenantid=EXCLUDED.lasttenantid, lastcompanyid=EXCLUDED.lastcompanyid, assignedtenantid=EXCLUDED.assignedtenantid, assignedcompanyid=EXCLUDED.assignedcompanyid;

