SELECT md5('mare:model:' || model_code)::uuid, model_code, model_name, TRUE, NOW(), md5('mare:tenant')::uuid, md5('mare:company:cho-lon')::uuid, selling_price, category, NULLIF(ingredients, '') FROM menu
ON CONFLICT (id) DO UPDATE SET model_code=EXCLUDED.model_code, model_name=EXCLUDED.model_name, is_active=TRUE, tenant_id=EXCLUDED.tenant_id, company_id=EXCLUDED.company_id, selling_price=EXCLUDED.selling_price, category=EXCLUDED.category, ingredients=EXCLUDED.ingredients;

SELECT md5('mare:bom:' || m.model_code)::uuid, m.model_name || ' BOM', 1, 'ACTIVE', NOW(), m.tenant_id, m.id, m.company_id FROM model m WHERE m.tenant_id=md5('mare:tenant')::uuid AND m.company_id=md5('mare:company:cho-lon')::uuid
ON CONFLICT (tenant_id, model_id, version) DO UPDATE SET bom_name=EXCLUDED.bom_name, status='ACTIVE', company_id=EXCLUDED.company_id;

DELETE FROM model_menu_option WHERE tenant_id=md5('mare:tenant')::uuid AND company_id=md5('mare:company:cho-lon')::uuid;
ON CONFLICT (id) DO UPDATE SET choices=EXCLUDED.choices, is_free=EXCLUDED.is_free, multi_select=TRUE;

