ON CONFLICT (token) DO UPDATE SET tenant_id=EXCLUDED.tenant_id, company_id=EXCLUDED.company_id, table_id=NULL, token_type='QUEUE_QR', description=EXCLUDED.description, enabled=TRUE;

-- Historical CUKCUK invoices, imported for September reporting only. Inventory has already been seeded from stock snapshot, so these rows do not deduct stock.
ON CONFLICT (id) DO UPDATE SET total_amount=EXCLUDED.total_amount, total_raw_cost=EXCLUDED.total_raw_cost, discount_amount=EXCLUDED.discount_amount, status='COMPLETED', payment_status='PAID', created_at=EXCLUDED.created_at, confirmed_at=EXCLUDED.confirmed_at, completed_at=EXCLUDED.completed_at;

ON CONFLICT (id) DO UPDATE SET quantity=EXCLUDED.quantity, unit_price=EXCLUDED.unit_price, unit_raw_cost=EXCLUDED.unit_raw_cost, line_total=EXCLUDED.line_total;

COMMIT;

